const items = $input.all();
if (!items || items.length === 0) {
  return [{ 
    json: { message: "No results found." },
    pairedItem: { item: 0 }
  }];
}

const first = items[0]?.json || {};
const keys = Object.keys(first);

// 🚨 FIX: Check for multiple rows FIRST
// 1️⃣ Multiple rows
if (items.length > 1) {
  const rowData = items.map(i => i.json);
  const hasTemporal = keys.some(k => 
    ['period', 'month', 'month_num', 'year', 'quarter', 'week', 'date'].includes(k.toLowerCase())
  );

  if (hasTemporal && keys.length >= 3) {
    const formatted = items.map((r, i) => {
      const row = r.json;
      const temporal = row.period || row.month_num || row.year || row.quarter || row.week || row.date;
      const otherFields = Object.entries(row)
        .filter(([k]) => !['period', 'month_num', 'year', 'quarter', 'week', 'date'].includes(k.toLowerCase()))
        .map(([k, v]) => `${k}: ${typeof v === 'number' ? Number(v).toLocaleString() : v}`)
        .join(", ");
      return `${i + 1}. Period: ${temporal} | ${otherFields}`;
    }).join("\n");

    return [{
      json: { message: formatted, raw: rowData },
      pairedItem: { item: 0 }
    }];
  }

  const formatted = items.map((r, i) => {
    const row = r.json;
    const values = Object.entries(row)
      .map(([k, v]) => `${k}: ${typeof v === 'number' ? Number(v).toLocaleString() : v}`)
      .join(", ");
    return `${i + 1}. ${values}`;
  }).join("\n");

  return [{
    json: { message: formatted, raw: rowData },
    pairedItem: { item: 0 }
  }];
}

// 2️⃣ Single scalar value with context message
if (keys.length === 1 && typeof first[keys[0]] !== "object") {
  const key = keys[0];
  const value = first[key];

  let message = `${key}: ${Number(value).toLocaleString()}`;

  // ✅ Add context for per-cadder averages
  try {
    const metaInfo = $('Build Safe SQL Query').first().json.meta;
    if (metaInfo?.operation === 'avg' && metaInfo?.target_field === 'Total_Price_NGN') {
      message += "\n\n_(Average calculated across individual cadders)_";
    }
  } catch (err) {
    // Ignore if meta not available
  }

  return [{
    json: { message, raw: first },
    pairedItem: { item: 0 }
  }];
}

// 3️⃣ Single complex object
if (items.length === 1 && keys.length > 1) {
  const formatted = Object.entries(first)
    .map(([k, v]) => `${k}: ${v}`)
    .join("\n");
  return [{
    json: { message: formatted, raw: first },
    pairedItem: { item: 0 }
  }];
}

// 4️⃣ Fallback
return [{
  json: {
    message: JSON.stringify(items.map(i => i.json), null, 2),
    raw: items.map(i => i.json)
  },
  pairedItem: { item: 0 }
}];

// Enhanced version - ensures clean string output
const item = $input.first().json;
const prompt = item.original_prompt;
const phone = item.original_phone;
const allowed_datasets = item.allowed_datasets || [];
const allowed_docs     = item.allowed_docs || [];
const public_docs      = ['Orange Group Employee Handbook.pdf'];
// Convert arrays to comma-separated strings for the system prompt
const datasetsString = allowed_datasets.join(', ');
const docsString = allowed_docs.join(', ');
const publicDocsString = public_docs.join(', ');

return [{
  json: {
    chatInput: prompt,
    original_phone: phone,
    allowed_datasets_text: datasetsString,
    allowed_docs_array: allowed_docs,  // Keep as array, don't convert to string
    allowed_docs_text: docsString,
    public_docs_text: publicDocsString
  }
}];

// ---------------------------
// INPUT FROM table_10 AGENT
// ---------------------------
const aiResponse = $input.first().json;
let responseText = aiResponse.output || aiResponse.text || '';

// ---------------------------
// GET ORIGINAL USER QUERY
// ---------------------------
const originalQuery = $('WhatsApp Trigger').first().json.messages[0].text.body;

// ---------------------------
// BRAND NORMALIZATION LOGIC
// ---------------------------
const brandVariations = {
  'Cannon Extra': ['cano', 'canon', 'cannon', 'canno', 'kanon', 'canoon'],
  'Laris': ['lari', 'lars', 'laris', 'larris', 'lares', 'larius']
};

const normalizeBrandName = (text) => {
  const lower = text.toLowerCase();
  for (const [canonical, variations] of Object.entries(brandVariations)) {
    for (const variant of variations) {
      const regex = new RegExp(`\\b${variant}\\b`, 'gi');
      text = text.replace(regex, canonical);
    }
  }
  return text;
};

const normalizeSingleBrand = (brandValue) => {
  if (!brandValue) return brandValue;
  const lowerBrand = String(brandValue).toLowerCase().trim();
  for (const [canonical, variations] of Object.entries(brandVariations)) {
    if (variations.some(v => v.toLowerCase() === lowerBrand)) {
      return canonical;
    }
  }
  return brandValue;
};

const normalizeFilters = (filters) => {
  if (!filters || typeof filters !== 'object') return filters;
  const normalized = { ...filters };

  if (normalized.brand) normalized.brand = normalizeSingleBrand(normalized.brand);
  if (normalized.Brand) normalized.Brand = normalizeSingleBrand(normalized.Brand);
  if (normalized.product) normalized.product = normalizeSingleBrand(normalized.product);

  return normalized;
};

console.log('Raw AI Response:', responseText);

// ---------------------------
// CLEAN ARTIFACTS
// ---------------------------
responseText = responseText
  .replace(/<function=.*?<\/function>/gs, '')
  .replace(/,function=.*?>/g, '')
  .trim();

// ---------------------------
// PARSE JSON BLOCK
// ---------------------------
const jsonPattern = /(\{(?:[^{}]|{[^{}]*})*\})/g;
const matches = responseText.match(jsonPattern);

if (matches) {
  for (const match of matches) {
    try {
      const parsed = JSON.parse(match);

      // ======================================================================
      // ✓ STRUCTURED INTENT BLOCK
      // ======================================================================
      if (parsed.intent_type?.toLowerCase() === 'structured') {
        if (!parsed.dataset_id) {
          throw new Error('Structured query missing dataset_id - AI Agent must call List Documents first');
        }

        const jsonIndex = responseText.indexOf(match);
        let cleanResponse = responseText.substring(0, jsonIndex).trim();

        cleanResponse = normalizeBrandName(cleanResponse);
        const normalizedFilters = normalizeFilters(parsed.filters);

        // ---------------------------
        // DETECT AGGREGATION PATTERNS
        // ---------------------------
        const perEntityPattern = /average.*(per|by|for each|of each).*(cadder|person|worker|seller|staff)/i;
        const cadderAveragePattern = /(cadder|person|worker|seller|staff).*(average|avg)|average.*(cadder|person|worker|seller|staff)/i;

        let aggregationLevel = 'simple';
        let entityField = null;

        if (perEntityPattern.test(originalQuery) || cadderAveragePattern.test(originalQuery)) {
          aggregationLevel = 'per_entity';
          entityField = 'Cadder';
        }

        // ---------------------------
        // OUTPUT STRUCTURED INTENT
        // ---------------------------
        const structuredOutput = {
          response: cleanResponse,
          intent_type: 'structured',
          handoff: parsed.handoff || 'Agent_2',
          dataset_id: parsed.dataset_id,
          operation: parsed.operation,
          target: parsed.target,
          filters: normalizedFilters,
          group_by: parsed.group_by || null,
          order_by: parsed.order_by || null,
          limit: parsed.limit || null,
          is_structured: true,
          raw_query: originalQuery, // ✅ ADD ORIGINAL QUERY
          aggregation_level: aggregationLevel, // ✅ ADD AGGREGATION LEVEL
          entity_field: entityField, // ✅ ADD ENTITY FIELD
          raw_intent: {
            ...parsed,
            filters: normalizedFilters
          },
        };

        // ====================================================================
        // ✓ DATASET VALIDATION
        // ====================================================================
        const datasetId = structuredOutput.dataset_id || structuredOutput.raw_intent?.dataset_id;
        if (!datasetId) {
          throw new Error('Structured query missing dataset_id. AI Agent must select a dataset from table_11');
        }

        // Attach validated dataset_id + table_name
        structuredOutput.validated_dataset_id = datasetId;
        structuredOutput.table_name = datasetId;

        return [{ json: structuredOutput }];
      }

      // ======================================================================
      // ✓ UNSTRUCTURED INTENT BLOCK
      // ======================================================================
      if (parsed.intent_type?.toLowerCase() === 'unstructured') {
        responseText = responseText.replace(match, '').trim();
        return [{
          json: { text: responseText },
          pairedItem: { text: responseText }
        }];
      }

    } catch (err) {
      console.error('JSON parse error:', err.message);
      continue;
    }
  }
}

// ============================================================================
// DEFAULT FALLBACK
// ============================================================================
return [{
  json: {
    text: responseText.trim()
  },
  pairedItem: {
    text: responseText.trim()
  }
}];

const input = $input.first().json;

// If not structured, skip downstream
if (!input.is_structured) {
  return [{
    json: {
      skip: true,
      reason: "Non-structured query — handled by Agent 1",
    },
  }];
}

// Escape helper
const esc = (val) => {
  if (val === null || val === undefined) return null;
  return String(val).replace(/'/g, "''");
};

// Field mapping for case-sensitive columnar schema (dynamically expandable)
const fieldMap = {
  'city': 'City',
  'brand': 'Brand',
  'month': 'Created_At',
  'year': 'Created_At',
  'carton': 'Carton',
  'cartons': 'Carton',
  'store': 'Store',
  'lga': 'LGA',
  'date': 'Created_At',
  'week': 'Created_At',
  'segment': 'LGA_Segment',
  'caddable_area': 'CADD_able_Area',
  'total_price': 'Total_Price_NGN',
  'price': 'Total_Price_NGN',
  'amount': 'Total_Price_NGN',
  'quantity': 'Carton',
  'location': 'City',
  'product': 'Brand',
  'customer': 'Store',
  'customers': 'Store',
  'locations': 'City',     
  'qty': 'Carton',         
  'quantities': 'Carton',  
  'revenue': 'Total_Price_NGN',  
  'sales': 'Total_Price_NGN',    
  'region': 'City',
  'volume': 'Carton',
  'people': 'Cadder',
  'cadders': 'Cadder',
  'personnels': 'Cadder',
  'workers': 'Cadder',
  'quarter': 'Created_At', 
  'q': 'Created_At',       
  'week': 'Created_At',    
  'day': 'Created_At',     
  'date': 'Created_At',    
};

// Normalize field names with case-insensitive mapping
const normalizeField = (field) => {
  if (!field) return null;
  const lower = String(field).toLowerCase().trim();
  return fieldMap[lower] || field;
};

// SQL operator mapping
const operatorMap = {
  'equals': '=',
  'equal': '=',
  'eq': '=',
  'not_equals': '!=',
  'not_equal': '!=',
  'ne': '!=',
  'greater_than': '>',
  'gt': '>',
  'greater_than_or_equal': '>=',
  'gte': '>=',
  'less_than': '<',
  'lt': '<',
  'less_than_or_equal': '<=',
  'lte': '<=',
  'like': 'LIKE',
  'ilike': 'ILIKE',
  'in': 'IN',
  'not_in': 'NOT IN',
  'between': 'BETWEEN',
  'is_null': 'IS NULL',
  'is_not_null': 'IS NOT NULL'
};

// Excel date conversion helper
const yearToExcelRange = (year) => {
  const yearNum = Number(year);
  if (isNaN(yearNum)) return null;

  const startDate = new Date(yearNum, 0, 1);
  const endDate = new Date(yearNum, 11, 31);
  const epoch = new Date(1899, 11, 30);

  const startSerial = Math.floor((startDate - epoch) / (1000 * 60 * 60 * 24));
  const endSerial = Math.floor((endDate - epoch) / (1000 * 60 * 60 * 24));

  return { start: startSerial, end: endSerial };
};

// Month name to number mapping
const monthMap = {
  'january': 1, 'jan': 1,
  'february': 2, 'feb': 2,
  'march': 3, 'mar': 3,
  'april': 4, 'apr': 4,
  'may': 5,
  'june': 6, 'jun': 6,
  'july': 7, 'jul': 7,
  'august': 8, 'aug': 8,
  'september': 9, 'sep': 9, 'sept': 9,
  'october': 10, 'oct': 10,
  'november': 11, 'nov': 11,
  'december': 12, 'dec': 12
};

// Helper for Orderby:
const parseOrderBy = (orderByStr) => {
  if (!orderByStr) return '';

  const parts = orderByStr.split(/\s+/).filter(part => part.trim());
  const field = parts[0].replace(/"/g, '');
  const direction = parts[1] || 'ASC';

  return `"${field}" ${direction}`;
};

// Helper for columns
const parseFieldList = (fieldString) => {
  if (!fieldString) return [];
  if (Array.isArray(fieldString)) return fieldString;
  if (typeof fieldString === 'string' && fieldString.includes(',')) {
    return fieldString.split(',').map(f => f.trim());
  }
  return [fieldString];
};

// Validate dataset
const datasetId = input.dataset_id || input.table_name || input.file_id || input.dataset || input.datasetId;
if (!datasetId) throw new Error("Missing dataset_id/table_name – cannot build SQL.");

// NEW: Validate format to prevent SQL injection
if (!/^[a-zA-Z0-9_-]+$/.test(datasetId)) {
  throw new Error("Invalid dataset_id format");
}

// Extract intent
const intent = input.raw_intent || input;
if (!intent || intent.intent_type !== "structured") {
  return [{
    json: {
      skip: true,
      reason: "Non-structured query — handled upstream (Agent 1).",
    },
  }];
}

// Get properties with enhanced operation handling
let op = (intent.operation || "select").toLowerCase().trim();
const targetRaw = intent.target || intent.measure || null;
const target = targetRaw ? normalizeField(targetRaw) : null;
let groupBy = intent.group_by || intent.groupby || null;
const orderBy = intent.order_by || intent.orderby || null;
const limit = intent.limit || intent.top || null;
const filters = intent.filters || {};

// Handle compound operations (count_distinct, sum_grouped, etc.)
let isDistinct = false;
let baseOp = op;

if (op.includes('_')) {
  const parts = op.split('_');
  if (parts.includes('distinct')) {
    isDistinct = true;
    baseOp = parts.filter(p => p !== 'distinct').join('_');
  }
}

// Map operation aliases
const operationMap = {
  'count_distinct': 'count',
  'countdistinct': 'count',
  'distinct_count': 'count',
  'sum_by': 'sum',
  'average': 'avg',
  'mean': 'avg',
  'maximum': 'max',
  'minimum': 'min',
  'total': 'sum',
  'aggregate': 'sum'
};

baseOp = operationMap[baseOp] || baseOp;

// Normalize group_by to array and map fields with case-insensitive handling
if (typeof groupBy === "string") groupBy = [groupBy];
if (!Array.isArray(groupBy)) groupBy = [];
groupBy = groupBy.map(g => normalizeField(g)).filter(Boolean);

// Auto-detect ranking/top queries from table_12, limit, or query keywords
const rankingKeywords = ['top', 'best', 'highest', 'most', 'leading', 'greatest'];
const bottomKeywords = ['bottom', 'worst', 'lowest', 'least', 'smallest'];

const isTopQuery = rankingKeywords.some(kw => 
  op.includes(kw) || 
  JSON.stringify(intent).toLowerCase().includes(kw)
);

const isBottomQuery = bottomKeywords.some(kw => 
  op.includes(kw) || 
  JSON.stringify(intent).toLowerCase().includes(kw)
);

const needsOrdering = (isTopQuery || isBottomQuery) && groupBy.length > 0 && 
  (baseOp === 'sum' || baseOp === 'count' || baseOp === 'avg' || baseOp === 'max' || baseOp === 'min');

// Build WHERE clause with advanced filtering support
const whereParts = [];
let yearValue = null;
let monthValue = null;
let weekValue = null;
let dateRangeFilter = null;

for (const [field, fval] of Object.entries(filters)) {
  if (fval === null || fval === undefined) continue;

  // Special handling for year
  if (field.toLowerCase() === 'year') {
    yearValue = Number(fval);
    continue;
  }

  // Special handling for quarter (Q1, Q2, Q3, Q4 or 1-4)
if (field.toLowerCase() === 'quarter' || field.toLowerCase() === 'q') {
  let quarterNum = null;
  if (typeof fval === 'string') {
    const qStr = fval.toLowerCase().replace(/[^0-9]/g, ''); // Extract number from "table_13"
    quarterNum = Number(qStr);
  } else {
    quarterNum = Number(fval);
  }

  if (!isNaN(quarterNum) && quarterNum >= 1 && quarterNum <= 4) {
    // Convert quarter to month range: Q1=1-3, Q2=4-6, Q3=7-9, Q4=10-12
    const quarterMonths = {
      1: [1, 2, 3],
      2: [4, 5, 6],
      3: [7, 8, 9],
      4: [10, 11, 12]
    };
    monthValue = quarterMonths[quarterNum];
  }
  continue;
}

  // Special handling for month (can be single value or array)
if (field.toLowerCase() === 'month') {
  if (Array.isArray(fval)) {
    monthValue = fval.map(m => {
      const monthStr = String(m).toLowerCase();
      return monthMap[monthStr] || Number(m);
    }).filter(m => !isNaN(m) && m >= 1 && m <= 12); // Validate 1-12 range
  } else {
    const monthStr = String(fval).toLowerCase();
    const parsed = monthMap[monthStr] || Number(fval);
    monthValue = (!isNaN(parsed) && parsed >= 1 && parsed <= 12) ? parsed : null;
  }
  continue;
}

  // Special handling for week (can be single value or array)
  if (field.toLowerCase() === 'week' || field.toLowerCase() === 'weeknum') {
    if (Array.isArray(fval)) {
      weekValue = fval.map(w => Number(w)).filter(w => !isNaN(w));
    } else {
      weekValue = Number(fval);
    }
    continue;
  }

  // Special handling for date_range
  if (field.toLowerCase() === 'date_range' && typeof fval === 'object') {
    dateRangeFilter = fval;
    continue;
  }

  // Map field to actual schema
  const actualField = normalizeField(field);

  // Handle complex filter objects with operators
  if (typeof fval === "object" && !Array.isArray(fval)) {
    if (fval.op && "value" in fval) {
      const val = fval.value;
      let opStr = String(fval.op).toLowerCase().trim();

      opStr = operatorMap[opStr] || opStr;

      // Handle BETWEEN operator
      if (opStr.toUpperCase() === 'BETWEEN' && Array.isArray(val) && val.length === 2) {
        whereParts.push(`"${actualField}" BETWEEN '${esc(val[0])}' AND '${esc(val[1])}'`);
        continue;
      }

      // Handle IN operator
      if (opStr.toUpperCase() === 'IN' && Array.isArray(val)) {
        const inValues = val.map(v => `'${esc(v)}'`).join(', ');
        whereParts.push(`"${actualField}" IN (${inValues})`);
        continue;
      }

      // Handle NOT IN operator
      if (opStr.toUpperCase() === 'NOT IN' && Array.isArray(val)) {
        const inValues = val.map(v => `'${esc(v)}'`).join(', ');
        whereParts.push(`"${actualField}" NOT IN (${inValues})`);
        continue;
      }

      // Handle LIKE/ILIKE operators
      if (opStr.toUpperCase() === 'LIKE' || opStr.toUpperCase() === 'ILIKE') {
        whereParts.push(`"${actualField}" ${opStr} '${esc(val)}'`);
        continue;
      }

      // Handle IS NULL / IS NOT NULL
      if (opStr.toUpperCase() === 'IS NULL' || opStr.toUpperCase() === 'IS NOT NULL') {
        whereParts.push(`"${actualField}" ${opStr}`);
        continue;
      }

      // Standard comparison operators
      whereParts.push(`"${actualField}" ${opStr} '${esc(val)}'`);
    }
  } 
  // Handle array values (IN operator)
  else if (Array.isArray(fval)) {
    const inValues = fval.map(v => `'${esc(v)}'`).join(', ');
    whereParts.push(`"${actualField}" IN (${inValues})`);
  }
  // Handle simple equality
  else {
    whereParts.push(`"${actualField}" = '${esc(fval)}'`);
  }
}

// Add temporal filters (date_range, year, month, week, quarter) in priority order
if (dateRangeFilter && dateRangeFilter.start && dateRangeFilter.end) {
  // Explicit date range takes highest priority
  whereParts.push(`"Created_At" BETWEEN '${esc(dateRangeFilter.start)}'::date AND '${esc(dateRangeFilter.end)}'::date`);
} else if (weekValue !== null) {
  // Week filter - can use Weeknum if available, or EXTRACT(WEEK FROM...)
  if (Array.isArray(weekValue)) {
    whereParts.push(`EXTRACT(WEEK FROM "table_14") IN (${weekValue.join(', ')})`);
  } else {
    whereParts.push(`EXTRACT(WEEK FROM "table_14") = ${weekValue}`);
  }
} else if (yearValue !== null && monthValue !== null) {
  // Year + Month combination using EXTRACT
  whereParts.push(`EXTRACT(YEAR FROM "table_14") = ${yearValue}`);
  if (Array.isArray(monthValue)) {
    whereParts.push(`EXTRACT(MONTH FROM "table_14") IN (${monthValue.join(', ')})`);
  } else {
    whereParts.push(`EXTRACT(MONTH FROM "table_14") = ${monthValue}`);
  }
} else if (monthValue !== null) {
  // Month only (no year specified) - applies to all years
  if (Array.isArray(monthValue)) {
    whereParts.push(`EXTRACT(MONTH FROM "table_14") IN (${monthValue.join(', ')})`);
  } else {
    whereParts.push(`EXTRACT(MONTH FROM "table_14") = ${monthValue}`);
  }
} else if (yearValue !== null) {
  // Year only
  whereParts.push(`EXTRACT(YEAR FROM "table_14") = ${yearValue}`);
}

const whereClause = whereParts.length ? `WHERE ${whereParts.join(" AND ")}` : "";

// Construct SQL
let sql = "";

// Handle additional query modifiers
const having = intent.having || null;

switch (baseOp) {
  case "count":
    if (isDistinct && target) {
      sql = `SELECT COUNT(DISTINCT "${target}") AS total FROM ${datasetId} ${whereClause};`;
    } else if (target && target.toLowerCase().startsWith("distinct:")) {
      const fieldRaw = target.split(":")[1];
      const field = normalizeField(fieldRaw);
      sql = `SELECT COUNT(DISTINCT "${field}") AS total FROM ${datasetId} ${whereClause};`;
    } else {
      sql = `SELECT COUNT(${isDistinct ? 'DISTINCT *' : '*'}) AS total FROM ${datasetId} ${whereClause};`;
    }
    break;

  case "sum":
  case "avg":
  case "min":
  case "max":
    if (!target) throw new Error(`Operation ${baseOp} requires a target field.`);
    const agg = baseOp.toUpperCase();

    // ⬇️ ADD THE NEW CODE HERE (before the existing if/else)
    if (baseOp === 'avg' && target && input.raw_query) {
    const rawQuery = input.raw_query.toLowerCase(); // ✅ Added declaration

    const impliesPerCadder = 
      /average.*(cadder|person|worker|seller|staff)/i.test(rawQuery) ||
      /(cadder|person|worker|seller|staff).*average/i.test(rawQuery) ||
      /per\s+(cadder|person|worker|seller|staff)/i.test(rawQuery) ||
      /each\s+(cadder|person|worker|seller|staff)/i.test(rawQuery) ||
      input.aggregation_level === 'per_entity';

    if (impliesPerCadder) {
      sql = `
        SELECT AVG(total_sales) AS value
        FROM (
          SELECT "Cadder", SUM("${target}") AS total_sales
          FROM ${datasetId}
          ${whereClause}
          GROUP BY "Cadder"
        ) AS cadder_totals;
      `.trim();
      break;
    }
  }

    if (groupBy.length > 0) {
  // Handle temporal grouping specially
  const aggSelectFields = [];
  const groupFields = [];

  groupBy.forEach(f => {
    const fLower = f.toLowerCase();

    if (fLower === 'month' || (fLower === 'created_at' && baseOp !== 'select')) {
      selectFields.push(`TO_CHAR("Created_At", 'YYYY-MM') AS period`);
      selectFields.push(`EXTRACT(MONTH FROM "table_14")::int AS month_num`);
      groupFields.push(`TO_CHAR("Created_At", 'YYYY-MM')`);
      groupFields.push(`EXTRACT(MONTH FROM "table_14")`);
    } else if (fLower === 'year') {
      selectFields.push(`EXTRACT(YEAR FROM "table_14")::int AS year`);
      groupFields.push(`EXTRACT(YEAR FROM "table_14")`);
    } else if (fLower === 'quarter' || fLower === 'q') {
      selectFields.push(`EXTRACT(QUARTER FROM "table_14")::int AS quarter`);
      groupFields.push(`EXTRACT(QUARTER FROM "table_14")`);
    } else if (fLower === 'week') {
