      if (opStr.toUpperCase() === 'IS NULL' || opStr.toUpperCase() === 'IS NOT NULL') {
        whereParts.push(`"${actualField}" ${opStr}`);
        continue;
      }

      // Standard comparison operators
      whereParts.push(`"${actualField}" ${opStr} '${esc(val)}'`);
    }
  } 
      // Handle array values (IN operator)
      else if (Array.isArray(fval)) {
        const inValues = fval.map(v => `'${esc(v)}'`).join(', ');
        whereParts.push(`"${actualField}" IN (${inValues})`);
      }
      // Handle simple equality
      else {
        whereParts.push(`"${actualField}" = '${esc(fval)}'`);
      }
    }

      // Add temporal filters (date_range, year, month, week, quarter) in priority order
      if (dateRangeFilter && dateRangeFilter.start && dateRangeFilter.end) {
        // Explicit date range takes highest priority
        whereParts.push(`"Created_At" BETWEEN '${esc(dateRangeFilter.start)}'::date AND '${esc(dateRangeFilter.end)}'::date`);
      } else if (weekValue !== null) {
        // Week filter - can use Weeknum if available, or EXTRACT(WEEK FROM...)
        if (Array.isArray(weekValue)) {
          whereParts.push(`EXTRACT(WEEK FROM "table_14") IN (${weekValue.join(', ')})`);
        } else {
          whereParts.push(`EXTRACT(WEEK FROM "table_14") = ${weekValue}`);
        }
      } else if (yearValue !== null && monthValue !== null) {
        // Year + Month combination using EXTRACT
        whereParts.push(`EXTRACT(YEAR FROM "table_14") = ${yearValue}`);
        if (Array.isArray(monthValue)) {
          whereParts.push(`EXTRACT(MONTH FROM "table_14") IN (${monthValue.join(', ')})`);
        } else {
          whereParts.push(`EXTRACT(MONTH FROM "table_14") = ${monthValue}`);
        }
      } else if (monthValue !== null) {
        // Month only (no year specified) - applies to all years
        if (Array.isArray(monthValue)) {
          whereParts.push(`EXTRACT(MONTH FROM "table_14") IN (${monthValue.join(', ')})`);
        } else {
          whereParts.push(`EXTRACT(MONTH FROM "table_14") = ${monthValue}`);
        }
      } else if (yearValue !== null) {
        // Year only
        whereParts.push(`EXTRACT(YEAR FROM "table_14") = ${yearValue}`);
      }

      const whereClause = whereParts.length ? `WHERE ${whereParts.join(" AND ")}` : "";

      // Construct SQL
      let sql = "";

      // Handle additional query modifiers
      const having = intent.having || null;

      switch (baseOp) {
        case "count":
          if (isDistinct && target) {
            sql = `SELECT COUNT(DISTINCT "${target}") AS total FROM ${datasetId} ${whereClause};`;
          } else if (target && target.toLowerCase().startsWith("distinct:")) {
            const fieldRaw = target.split(":")[1];
            const field = normalizeField(fieldRaw);
            sql = `SELECT COUNT(DISTINCT "${field}") AS total FROM ${datasetId} ${whereClause};`;
          } else {
            sql = `SELECT COUNT(${isDistinct ? 'DISTINCT *' : '*'}) AS total FROM ${datasetId} ${whereClause};`;
          }
          break;

  case "sum":
  case "avg":
  case "min":
  case "max":
    if (!target) throw new Error(`Operation ${baseOp} requires a target field.`);
    const agg = baseOp.toUpperCase();

    // ⬇️ Columns Aggregation for Cadders
    if (baseOp === 'avg' && target && input.raw_query) {
    const rawQuery = input.raw_query.toLowerCase(); // ✅ Added declaration

    const impliesPerCadder = 
      /average.*(cadder|person|worker|seller|staff)/i.test(rawQuery) ||
      /(cadder|person|worker|seller|staff).*average/i.test(rawQuery) ||
      /per\s+(cadder|person|worker|seller|staff)/i.test(rawQuery) ||
      /each\s+(cadder|person|worker|seller|staff)/i.test(rawQuery) ||
      input.aggregation_level === 'per_entity';

    if (impliesPerCadder) {
      sql = `
        SELECT AVG(total_sales) AS value
        FROM (
          SELECT "Cadder", SUM("${target}") AS total_sales
          FROM ${datasetId}
          ${whereClause}
          GROUP BY "Cadder"
        ) AS cadder_totals;
      `.trim();
      break;
    }
  }

    // ⬇️ ENHANCED TEMPORAL AGGREGATION LOGIC HERE
    if ((baseOp === 'avg' || baseOp === 'sum') && input.temporal_aggregation) {
      const temporalSqlMap = {
        'daily': 'DATE("Created_At")',
        'weekly': 'EXTRACT(WEEK FROM "table_14")', 
        'monthly': 'EXTRACT(MONTH FROM "table_14")',
        'quarterly': 'EXTRACT(QUARTER FROM "table_14")',
        'yearly': 'EXTRACT(YEAR FROM "table_14")'
      };

      const temporalGroup = temporalSqlMap[input.temporal_aggregation];
      if (temporalGroup) {
        // CHOOSE BETWEEN BREAKDOWN VS AGGREGATED
        if (input.output_type === 'breakdown') {
          // BREAKDOWN: List all periods with their values
          sql = `
            SELECT ${temporalGroup} as period, 
                   ${baseOp.toUpperCase()}("${target}") AS value
            FROM ${datasetId}
            ${whereClause}
            GROUP BY ${temporalGroup}
            ORDER BY period;
          `.trim();
        } else {
          // AGGREGATED: Single result (average/total of period totals)
          sql = `
            SELECT ${baseOp.toUpperCase()}(period_totals) AS value
            FROM (
              SELECT SUM("${target}") AS period_totals
              FROM ${datasetId}
              ${whereClause}
              GROUP BY ${temporalGroup}
            ) AS temporal_agg;
          `.trim();
        }
         break;
      }
    }
    if (groupBy.length > 0) {
  // Handle temporal grouping specially
  const aggSelectFields = [];
  const groupFields = [];

  groupBy.forEach(f => {
    const fLower = f.toLowerCase();

    if (fLower === 'month' || (fLower === 'created_at' && baseOp !== 'select')) {
      selectFields.push(`TO_CHAR("Created_At", 'YYYY-MM') AS period`);
      selectFields.push(`EXTRACT(MONTH FROM "table_14")::int AS month_num`);
      groupFields.push(`TO_CHAR("Created_At", 'YYYY-MM')`);
      groupFields.push(`EXTRACT(MONTH FROM "table_14")`);
    } else if (fLower === 'year') {
      selectFields.push(`EXTRACT(YEAR FROM "table_14")::int AS year`);
      groupFields.push(`EXTRACT(YEAR FROM "table_14")`);
    } else if (fLower === 'quarter' || fLower === 'q') {
      selectFields.push(`EXTRACT(QUARTER FROM "table_14")::int AS quarter`);
      groupFields.push(`EXTRACT(QUARTER FROM "table_14")`);
    } else if (fLower === 'week') {
      selectFields.push(`EXTRACT(WEEK FROM "table_14")::int AS week`);
      groupFields.push(`EXTRACT(WEEK FROM "table_14")`);
    } else if (fLower === 'day' || fLower === 'date') {
      selectFields.push(`"Created_At"::date AS date`);
      groupFields.push(`"Created_At"::date`);
    } else {
      selectFields.push(`"${f}"`);
      groupFields.push(`"${f}"`);
    }
  });

  const selectFieldsStr = selectFields.join(", ");
  const groupFieldsStr = groupFields.join(", ");

      let finalOrderBy = orderBy;
      let finalLimit = limit;

      // Auto-detect ordering for ranking queries
      if (needsOrdering && !orderBy) {
        finalOrderBy = isBottomQuery ? "value ASC" : "value DESC";
      }

      // Auto-add limit for ranking queries
      if (needsOrdering && !limit) {
        finalLimit = 10;
      }

      sql = `
  SELECT ${selectFieldsStr},
    ${agg}(${isDistinct ? 'DISTINCT ' : ''}"${target}") AS value
  FROM ${datasetId}
  ${whereClause}
  GROUP BY ${groupFieldsStr}
  ${having ? `HAVING ${having}` : ""}
  ${finalOrderBy ? `ORDER BY ${parseOrderBy(finalOrderBy)}` : ""}  
  ${finalLimit ? `LIMIT ${Number(finalLimit)}` : ""}; 
`.trim();
    } else {
      sql = `SELECT ${agg}(${isDistinct ? 'DISTINCT ' : ''}"${target}") AS value FROM ${datasetId} ${whereClause};`;
    }
    break;

  case "select":
  case "list":
  case "fetch":
    const listSelectFields = target ? 
    parseFieldList(target).map(f => {
      const mappedField = normalizeField(f);
      return `"${mappedField}"`;
    }).join(", ") : 
    "*";

  sql = `
    SELECT ${isDistinct ? 'DISTINCT' : ''} ${listSelectFields}
    FROM ${datasetId}
    ${whereClause}
    ${orderBy ? `ORDER BY ${parseOrderBy(orderBy)}` : ""}
    ${limit ? `LIMIT ${Number(limit)}` : ""};
  `.trim();
  break;

  case "top":
  case "bottom":
    if (!target) throw new Error(`Operation ${baseOp} requires a target field for sorting.`);
    const sortOrder = baseOp === "top" ? "DESC" : "ASC";
    const topLimit = limit || 10;

    sql = `
      SELECT *
      FROM ${datasetId}
      ${whereClause}
      ORDER BY "${target}" ${sortOrder}
      LIMIT ${Number(topLimit)};
    `.trim();
    break;

  case "group":
  case "groupby":
    if (!groupBy || groupBy.length === 0) throw new Error("Group operation requires group_by fields.");

    const grpSelectFields = groupBy.map(f => `"${f}"`).join(", ");
    const grpGroupFields = groupBy.map(f => `"${f}"`).join(", ");

    sql = `
      SELECT ${grpSelectFields},
        COUNT(${isDistinct ? 'DISTINCT *' : '*'}) AS count
        ${target ? `, SUM("${target}") AS total` : ''}
      FROM ${datasetId}
      ${whereClause}
      GROUP BY ${grpGroupFields}
      ${having ? `HAVING ${having}` : ""}
      ${orderBy ? `ORDER BY ${parseOrderBy(orderBy)}` : "ORDER BY count DESC"}
      ${limit ? `LIMIT ${Number(limit)}` : ""};
    `.trim();
    break;

  default:
    sql = `SELECT * FROM ${datasetId} ${whereClause} ${limit ? `LIMIT ${Number(limit)}` : ''};`;
}

// Final safety check
if (!sql.trim().toLowerCase().startsWith("select")) {
  throw new Error("Unsafe SQL detected — only SELECT queries allowed.");
}

// Return formatted response
return [{
  json: {
    query: sql.trim(),
    dataset_id: datasetId,
    meta: {
      built_by: "[ID]",
      operation: baseOp,
      is_distinct: isDistinct,
      target_field: target,
      group_fields: groupBy,
      date_filters: {
        year: yearValue,
        month: Array.isArray(monthValue) ? monthValue : monthValue,
        week: Array.isArray(weekValue) ? weekValue : weekValue
      },
      intent_summary: `${baseOp.toUpperCase()}${isDistinct ? ' DISTINCT' : ''} on ${target || "rows"}${
        groupBy.length ? " grouped by " + groupBy.join(", ") : ""
      }`,
    },
  },
}];
